void ProviderAgent::parse_sse_frame(const std::string& frame)
{
    std::string payload;
    std::istringstream lines(frame);
    std::string line;
    while (std::getline(lines, line)) {
        if (!line.empty() && line.back() == '\r')
            line.pop_back();
        if (line.rfind("data:", 0) == 0) {
            std::string part = line.substr(5);
            if (!part.empty() && part.front() == ' ')
                part.erase(part.begin());
            if (!payload.empty())
                payload += '\n';
            payload += part;
        }
    }
    if (payload.empty() || payload == "[DONE]")
        return;
    for (StreamEvent& event : m_codec->parse(payload))
        handle(std::move(event));
}

void ProviderAgent::handle(StreamEvent event)
{
    // The provider has accepted the request: what it carried is now part of
    // the chat. A request it refused leaves no trace.
    record();
    switch (event.kind) {
    case StreamEvent::Kind::TextDelta: m_events.push_back(AgentEvent::delta(std::move(event.text))); break;
    case StreamEvent::Kind::TurnComplete: finish_response(std::move(event)); break;
    case StreamEvent::Kind::Failed: fail(std::move(event.error)); break;
    // An error inside a reply, or a reply cut short or unreadable, names
    // nothing a person can act on.
    case StreamEvent::Kind::ServiceError: unexpected(event.text, {});
    }
}

void ProviderAgent::finish_response(StreamEvent event)
{
    if (m_terminal_seen)
        return;
    m_terminal_seen = true;
    if (m_config.usage_listener && event.usage)
        m_config.usage_listener(*event.usage);
    m_queued_calls.clear();
    m_step_skills.clear();
    m_results = RecordItem{RecordItem::Kind::Results};
    m_failed_call.clear();

    if (elapsed_ms)
        payload["elapsedMs"] = *elapsed_ms;
    if (error)
        payload["error"] = json{{"code", error->code}, {"message", error->message}, {"retryable", error->retryable}};
    send_envelope(Protocol::kSetupStatus, payload.dump(), correlation_id);
}

void AgentHost::handle_setup_check_key(const std::string& envelope_id, const std::string& payload_json)
{
    cancel_conversation_title();
    // Only Preferences sends this, and its host runs no reply.
    if (agent_busy())
        throw RuntimeError("jusprin-agent-bridge: configuring AI asked while a reply runs");
    if (!m_setup)
        throw std::logic_error("jusprin-agent-bridge: AI setup asked of a host with none");
    const json payload = json::parse(payload_json);

    SetupCredentials credentials;
    credentials.provider = payload.value("provider", "");
    credentials.api_key  = payload.value("apiKey", "");
    credentials.model    = payload.value("model", "");
    credentials.endpoint = payload.value("endpoint", "");

    // The key field sends nothing while empty.
    if (credentials.api_key.empty())
        throw RuntimeError("jusprin-agent-bridge: setup_check_key carries no key");
    if (m_setup->busy()) {
        send_bridge_error("setup_busy", translated(L("A credential check is already running.")), envelope_id);
        return;
    }

    // The pending credentials outlive the request so a verified key can be
    // persisted without the page holding or re-sending the secret.
    m_setup_pending = credentials;
    if (!m_setup->start_check(credentials)) {
        const AgentError error{"unsupported_provider",
                               translated(L("This build cannot verify a key for that provider yet.")), false};
        send_setup_status("error", envelope_id, std::nullopt, error);
        m_setup_pending.reset();
        return;
    }
    send_setup_status("checking", envelope_id);
}

void AgentHost::handle_setup_cancel()
{
    if (!m_setup || !m_setup->busy())
        return; // Cancelling a finished check is a benign race.
    m_setup->cancel();
    m_setup_pending.reset();
    send_setup_status("idle");
}

void AgentHost::handle_setup_remove_key(const std::string& envelope_id, const std::string& payload_json)
{
    // A chat title being written is not a reply; it gives way, as it does to
    // a key check.
    cancel_conversation_title();
    if (!m_setup)
        throw std::logic_error("jusprin-agent-bridge: AI setup asked of a host with none");
    // Only Preferences sends this, and its host runs no reply.
    if (agent_busy())
        throw RuntimeError("jusprin-agent-bridge: removing a key asked while a reply runs");
    // Remove is greyed out while a key is checked.
    if (m_setup->busy())
        throw RuntimeError("jusprin-agent-bridge: setup_remove_key while a key check runs");
    remove_saved_key(json::parse(payload_json).value("provider", ""));
    send_setup_keys(envelope_id);
}

void AgentHost::remove_saved_key(const std::string& provider)
{
    m_setup->remove_key(provider);
    m_rejected_keys.erase(provider);

    // The agent in use may hold the removed key. It is rebuilt from the keys
    // still stored, as a launch would build it; with none left, the dock is
    // back to being unconfigured.
    if (m_model_source) {
        AgentServicePtr agent = m_model_source->configured_providers().empty() ? nullptr :
                                m_model_source->make_agent(default_chat_model());
        const AgentAvailability availability = agent ? AgentAvailability::Ready : AgentAvailability::Unavailable;
        set_agent(std::move(agent), availability);
    } else if (m_setup->saved_keys().empty()) {
        set_agent(nullptr, AgentAvailability::Unavailable);
    }
}

void AgentHost::handle_delete_account(const std::string& envelope_id)
{
    const auto answer = [this, envelope_id](bool deleted) {
        if (m_handshake)
            send_envelope(Protocol::kAccountDeleted, json{{"deleted", deleted}}.dump(), envelope_id);
    };
    // Its key goes once the server has deleted the account, and a reply that
    // is still running would be left holding it, so one waits for the other.
    // The Preferences window asks this of a host with no chat of its own; the
    // reply runs in another host's.
    const bool reply_running = agent_busy() || (m_reply_running_elsewhere && m_reply_running_elsewhere());
    if (!m_model_source || !m_setup || reply_running || m_setup->busy()) {
        answer(false);
        return;
    }
    m_model_source->delete_account([this, answer](bool deleted) {
        if (deleted) {
            // Signed out the way Sign out does, whatever happens next: the
            // account no longer exists to sign in as.
            for (const SavedKey& saved : m_setup->saved_keys())
                if (const ProviderProfile* profile = profile_for(saved.provider); profile != nullptr && profile->account_sign_in)
                    remove_saved_key(saved.provider);
            send_setup_keys();
            request_account();
            request_account_box();
        }
        answer(deleted);
    });
}

void AgentHost::send_setup_keys(const std::string& correlation_id)
{
    if (!m_setup || !m_handshake)
        return;
    json keys = json::array();
    for (const SavedKey& saved : m_setup->saved_keys()) {
        const auto refused = m_rejected_keys.find(saved.provider);
        json key{{"provider", saved.provider}, {"hint", saved.hint},
                 {"rejected", refused != m_rejected_keys.end() && refused->second == saved.hint}};
        if (!saved.account.empty())
            key["account"] = saved.account;
        keys.push_back(std::move(key));
    }
    send_envelope(Protocol::kSetupKeys, json{{"keys", std::move(keys)}}.dump(), correlation_id);
}

