{
    m_commit(credentials);
}

std::vector<SavedKey> ProviderKeySetup::saved_keys() const
{
    std::vector<SavedKey> saved;
    if (!m_keys.load)
        return saved;
    for (const ProviderProfile& profile : provider_profiles()) {
        const std::string key = m_keys.load(profile.id);
        if (key.empty())
            continue;
        SavedKey entry{profile.id, api_key_hint(profile.id, key), {}};
        if (profile.account_sign_in && m_cloud)
            if (const std::optional<CloudAccountRecord> account = m_cloud->account())
                entry.account = account->email;
        saved.push_back(std::move(entry));
    }
    return saved;
}

void ProviderKeySetup::remove_key(const std::string& provider)
{
    if (!setup_provider_supported(provider))
        throw RuntimeError("jusprin-agent-setup: removing the key of " + provider + ", which this build has no provider for");
    if (profile_for(provider)->account_sign_in) {
        if (!m_cloud)
            throw std::logic_error("jusprin-agent-setup: signing out of a build with no account sign-in");
        m_cloud->sign_out();
        return;
    }
    if (!m_keys.remove)
        throw std::logic_error("jusprin-agent-setup: removing a key from a setup with no key store");
    m_keys.remove(provider);
}

int ProviderKeySetup::elapsed_ms() const
{
    return static_cast<int>(std::chrono::duration_cast<std::chrono::milliseconds>(m_clock() - m_started).count());
}

SetupOutcome ProviderKeySetup::finish_ok()
{
    SetupOutcome outcome;
    outcome.ok         = true;
    outcome.elapsed_ms = elapsed_ms();
    // Drop the probe turn so the verified service is handed over idle, with
    // no partial response left for the user's first real message to inherit.
    m_candidate->cancel();
    outcome.service = std::move(m_candidate);
    m_candidate.reset();
    return outcome;
}

