                 std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - m_started).count());
    m_usage.total = m_usage.input + m_usage.output;
    event.usage   = m_usage;
    event.resend  = m_stop_reason == "pause_turn";
    return event;
}

