(function () {
  const base = 'http://127.0.0.1:8765';
  const log = (what) => fetch(base + '/log', { method: 'POST', body: JSON.stringify(what) }).catch(() => {});
  const view = () => {
    const s = window.__jusprinTest && window.__jusprinTest.state();
    if (!s) return null;
    const messages = (s.messages || s.conversation?.messages || []);
    const last = messages[messages.length - 1];
    return { setup: s.setup, lastMessage: last && { role: last.role, state: last.state, error: last.error, text: last.text } };
  };
  const tick = async () => {
    try {
      const cmd = await (await fetch(base + '/cmd')).json();
      if (cmd.run && window.__jusprinTest) {
        if (cmd.run === 'checkKey') window.__jusprinTest.checkKey(cmd.provider, cmd.apiKey);
