        if (cmd.run === 'dom') log({ tag: cmd.tag, text: document.body.innerText.slice(-1500) });
      }
    } catch (e) { log({ error: String(e) }); }
    setTimeout(tick, 400);
  };
  setTimeout(tick, 1000);
})();

